using System.Collections.Generic;public class Solution{public void WallsAndGates(int[][]r){if(r.Length==0)return;var q=new Queue<(int,int)>();for(int i=0;i<r.Length;i++)for(int j=0;j<r[0].Length;j++)if(r[i][j]==0)q.Enqueue((i,j));int[][]d={new[]{1,0},new[]{-1,0},new[]{0,1},new[]{0,-1}};while(q.Count>0){var(x,y)=q.Dequeue();foreach(var z in d){int a=x+z[0],b=y+z[1];if(a>=0&&b>=0&&a<r.Length&&b<r[0].Length&&r[a][b]==int.MaxValue){r[a][b]=r[x][y]+1;q.Enqueue((a,b));}}}}}
